#include <stdint.h>
#include <stdio.h>
#include "stm32f7xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

uint8_t col_hits[4] = {0};

// Passed from the keypad ISRs to the main loop
volatile char last_key = 0;     // Most recent key pressed
volatile uint8_t key_ready = 0; // Set by ISR, cleared by main loop

// LCD control line macros
#define EN_HIGH()   (GPIOA->BSRR = (1UL << 15))
#define EN_LOW()    (GPIOA->BSRR = (1UL << (15 + 16)))

#define RS_HIGH()   (GPIOA->BSRR = (1UL << 8))
#define RS_LOW()    (GPIOA->BSRR = (1UL << (8 + 16)))

// Passive buzzer is driven by TIM3 CH1 PWM on PB4 (2 kHz square wave).
// The timer always runs; "off" just sets the duty cycle to 0%.
#define BUZZER_PERIOD 500  // 1 MHz timer tick / 500 = 2 kHz tone
#define BUZZER_ON()  (TIM3->CCR1 = BUZZER_PERIOD / 2) // 50% duty -> tone
#define BUZZER_OFF() (TIM3->CCR1 = 0)                 // 0% duty  -> silent (pin low)

// Buzzer durations from the lab instructions
#define BEEP_MS          100   // Short beep on every keypress
#define GRANTED_TONE_MS  2000  // Continuous 2-second tone on Access Granted
#define LOCKOUT_PULSE_MS 500   // Pulse on alternating seconds during the lockout countdown

const unsigned char key_val[4][4] = {
		{'1', '2', '3', 'A'},
		{'4', '5', '6', 'B'},
		{'7', '8', '9', 'C'},
		{'*', '0', '#', 'D'},
};

/*
 * Pinout:
 * PI1  = D13 = C1
 * PI2  = D8  = C2
 * PI3  = D7  = C3
 * PI0  = D5  = C4
 * PB8  = D15 = R1
 * PB9  = D14 = R2
 * PB14 = D12 = R3
 * PB15 = D11 = R4
 *
 * PF6  = A5  = LCD D4
 * PF7  = A4  = LCD D5
 * PF8  = A3  = LCD D6
 * PF9  = A2  = LCD D7
 * PA8  = D10 = LCD RS
 * PA15 = D9  = LCD E
 *
 * PB4  = D3  = Buzzer
 * */

/*
 * Phase 1 idle state:
 *   Rows    = outputs driven low
 *   Columns = inputs with pull-up resistors
 * Call during init and after every scan.
 */
void keypad_idle_state(void)
{
    // Drive all rows low (set ODR before switching to output so there is no glitch)
    GPIOB->BSRR = (1UL << (8 + 16));
    GPIOB->BSRR = (1UL << (9 + 16));
    GPIOB->BSRR = (1UL << (14 + 16));
    GPIOB->BSRR = (1UL << (15 + 16));

    // PB8  = D15 = R1
    GPIOB->MODER &= ~(3UL << (8 * 2));
    GPIOB->MODER |= (1UL << (8 * 2));
    GPIOB->PUPDR &= ~(3UL << (8 * 2));

    // PB9  = D14 = R2
    GPIOB->MODER &= ~(3UL << (9 * 2));
    GPIOB->MODER |= (1UL << (9 * 2));
    GPIOB->PUPDR &= ~(3UL << (9 * 2));

    // PB14 = D12 = R3
    GPIOB->MODER &= ~(3UL << (14 * 2));
    GPIOB->MODER |= (1UL << (14 * 2));
    GPIOB->PUPDR &= ~(3UL << (14 * 2));

    // PB15 = D11 = R4
    GPIOB->MODER &= ~(3UL << (15 * 2));
    GPIOB->MODER |= (1UL << (15 * 2));
    GPIOB->PUPDR &= ~(3UL << (15 * 2));

    // Set all columns as digital inputs w/ pull up resistor
    // PI1  = D13 = C1
    GPIOI->MODER &= ~(3UL << (1 * 2));
    GPIOI->PUPDR &= ~(3UL << (1 * 2));
    GPIOI->PUPDR |=  (1UL << (1 * 2));

    // PI2  = D8  = C2
    GPIOI->MODER &= ~(3UL << (2 * 2));
    GPIOI->PUPDR &= ~(3UL << (2 * 2));
    GPIOI->PUPDR |=  (1UL << (2 * 2));

    // PI3  = D7  = C3
    GPIOI->MODER &= ~(3UL << (3 * 2));
    GPIOI->PUPDR &= ~(3UL << (3 * 2));
    GPIOI->PUPDR |=  (1UL << (3 * 2));

    // PI0  = D5  = C4
    GPIOI->MODER &= ~(3UL << (0 * 2));
    GPIOI->PUPDR &= ~(3UL << (0 * 2));
    GPIOI->PUPDR |=  (1UL << (0 * 2));
}

/*
 * Phase 2 row scan.
 *   col = column index into key_val (0 = C1 ... 3 = C4)
 * Returns the key character, or 0 if no row was found (e.g. a bounce).
 * Leaves the pins in the scan state - call keypad_idle_state() afterwards.
 */
char keypad_scan(unsigned int col)
{
    if (col >= 4) return 0;

    // Column index -> pin: C1 = PI1, C2 = PI2, C3 = PI3, C4 = PI0
    unsigned int pin = (col + 1) % 4;

    // Drive ONLY the triggered column low (set ODR before switching to output).
    // It's already being held low through the pressed key, so this makes no edge.
    // The other columns stay pull-up inputs, so they see no falling edge and
    // don't fire false interrupts.
    // Done before flipping the rows so the column is never left floating high.
    GPIOI->BSRR = (1UL << (pin + 16));
    GPIOI->MODER &= ~(3UL << (pin * 2));
    GPIOI->MODER |=  (1UL << (pin * 2));
    GPIOI->PUPDR &= ~(3UL << (pin * 2));

    // Flip rows to inputs with pull-up resistors
    // PB8  = D15 = R1
    GPIOB->MODER &= ~(3UL << (8 * 2));
    GPIOB->PUPDR &= ~(3UL << (8 * 2));
    GPIOB->PUPDR |= (1UL << (8 * 2));

    // PB9  = D14 = R2
    GPIOB->MODER &= ~(3UL << (9 * 2));
    GPIOB->PUPDR &= ~(3UL << (9 * 2));
    GPIOB->PUPDR |= (1UL << (9 * 2));

    // PB14 = D12 = R3
    GPIOB->MODER &= ~(3UL << (14 * 2));
    GPIOB->PUPDR &= ~(3UL << (14 * 2));
    GPIOB->PUPDR |= (1UL << (14 * 2));

    // PB15 = D11 = R4
    GPIOB->MODER &= ~(3UL << (15 * 2));
    GPIOB->PUPDR &= ~(3UL << (15 * 2));
    GPIOB->PUPDR |= (1UL << (15 * 2));

    // Short delay so the row pull-ups can settle
    for (volatile int d = 0; d < 50; d++);

    unsigned int row = 0xFF;

    // Check PB8  = D15 = R1
    // Check PB9  = D14 = R2
    // Check PB14 = D12 = R3
    // Check PB15 = D11 = R4
    if (!(GPIOB->IDR & 0x0100)) {
        row = 0;
    } else if (!(GPIOB->IDR & 0x0200)) {
        row = 1;
    } else if (!(GPIOB->IDR & 0x4000)) {
        row = 2;
    } else if (!(GPIOB->IDR & 0x8000)) {
        row = 3;
    }

    if (row < 4 && col < 4) {
        return key_val[row][col];
    }
    return 0;
}

// TIM4 free-runs at 1 tick/ms, so we only read it and never start/stop/reset it.
// This makes it safe to call from main AND from an ISR that interrupts a delay.
void TIM4_DelayMs(uint32_t ms) {
    if (ms == 0) return;

    uint16_t start = TIM4->CNT;

    // <= so at least 'ms' full ticks pass (the first tick may be partial)
    while ((uint16_t)(TIM4->CNT - start) <= ms);
}

// Buzzer state for non-blocking beeps (checked by the main loop)
static uint8_t  buzzer_active = 0; // 1 while the tone is playing
static uint16_t buzzer_start  = 0; // TIM4->CNT when the tone started
static uint16_t buzzer_len    = 0; // How long the tone should last (ms)

// Start a tone that lasts 'ms' milliseconds. Returns immediately.
void Buzzer_Beep(uint16_t ms) {
    BUZZER_ON();
    buzzer_start  = TIM4->CNT;
    buzzer_len    = ms;
    buzzer_active = 1;
}

// Poll from the main loop: turns the tone off once its time is up.
void Buzzer_Update(void) {
    if (buzzer_active && (uint16_t)(TIM4->CNT - buzzer_start) >= buzzer_len) {
        BUZZER_OFF();
        buzzer_active = 0;
    }
}

void LCD_Nibble(uint8_t data, uint8_t regsel) {
    if (regsel) {
        RS_HIGH();
    } else {
        RS_LOW();
    }

    // Configure each bit:
    // D4 = PF6
    if (data & 0x01) {
        GPIOF->BSRR = (1UL << 6);
    } else {
        GPIOF->BSRR = (1UL << (6 + 16));
    }

    // D5 = PF7
    if (data & 0x02) {
        GPIOF->BSRR = (1UL << 7);
    } else {
        GPIOF->BSRR = (1UL << (7 + 16));
    }

    // D6 = PF8
    if (data & 0x04) {
        GPIOF->BSRR = (1UL << 8);
    } else {
        GPIOF->BSRR = (1UL << (8 + 16));
    }

    // D7 = PF9
    if (data & 0x08) {
        GPIOF->BSRR = (1UL << 9);
    } else {
        GPIOF->BSRR = (1UL << (9 + 16));
    }

    // Cycle Enable pulse to latch!
    EN_HIGH();
    TIM4_DelayMs(2); // Setup time is 1 ms
    EN_LOW(); // LATCH!
    TIM4_DelayMs(2);
}

// Interrupts are blocked while a byte is sent so an ISR can't split the two nibbles
// (that knocks the LCD out of 4-bit sync). PRIMASK is restored, not just re-enabled,
// so this also works when called from inside an ISR.
void LCD_Cmd(uint8_t cmd) {
    uint32_t primask = __get_PRIMASK();
    __disable_irq();
    LCD_Nibble(cmd >> 4, 0);
    LCD_Nibble(cmd & 0x0F, 0);
    __set_PRIMASK(primask);
}

void LCD_Data(uint8_t data) {
    uint32_t primask = __get_PRIMASK();
    __disable_irq();
    LCD_Nibble(data >> 4, 1);
    LCD_Nibble(data & 0x0F, 1);
    __set_PRIMASK(primask);
}

void LCD_Initialize(void) {
    // Wait for VDD stability
    TIM4_DelayMs(100);

    // HD44780 4-bit mode
    LCD_Nibble(0x03, 0);
    TIM4_DelayMs(10);
    LCD_Nibble(0x03, 0);
    TIM4_DelayMs(2);
    LCD_Nibble(0x03, 0);
    TIM4_DelayMs(2);

    LCD_Nibble(0x02, 0);
    TIM4_DelayMs(2);

    // Now that the LCD is in 4-bit mode, initialize commands!
    LCD_Cmd(0x28); // 4-bit mode configuration
    LCD_Cmd(0x0C); // Display ON, hide cursor
    LCD_Cmd(0x06); // Increment write address
    LCD_Cmd(0x01); // Execute clear layout
    TIM4_DelayMs(5);
}

// Send each character through and do pointer arithmetic
void LCD_DisplayString(char *str) {
    LCD_Cmd(0x01); // Execute clear layout

    while (*str) {
        LCD_Data(*str++);
    }
}

int main(void)
{
    // Init registers

	// Bit 8 = GPIOI, Bit 5 = GPIOF, Bit 1 = GPIOB, Bit 0 = GPIOA
	RCC->AHB1ENR |= (1UL << 8) | (1UL << 5) | (1UL << 1) | (1UL << 0);

    // Bit 14 enables SYSCFG clock (for routing GPIO to EXTI)
    RCC->APB2ENR |= (1UL << 14);

    // Bit 1 enables TIM3 clock (buzzer PWM), Bit 2 enables TIM4 clock (1 ms ticker)
    RCC->APB1ENR |= (1UL << 1) | (1UL << 2);

    // Initialize GPIO pins (rows low outputs, columns pull-up inputs)
    keypad_idle_state();

    // LCD D4 (PF6, A5) -> Output
    GPIOF->MODER  &= ~(3UL << (6 * 2));
    GPIOF->MODER  |=  (1UL << (6 * 2));
    GPIOF->OTYPER &= ~(1UL << 6);
    GPIOF->OSPEEDR |= (3UL << (6 * 2));

    // LCD D5 (PF7, A4) -> Output
    GPIOF->MODER  &= ~(3UL << (7 * 2));
    GPIOF->MODER  |=  (1UL << (7 * 2));
    GPIOF->OTYPER &= ~(1UL << 7);
    GPIOF->OSPEEDR |= (3UL << (7 * 2));

    // LCD D6 (PF8, A3) -> Output
    GPIOF->MODER  &= ~(3UL << (8 * 2));
    GPIOF->MODER  |=  (1UL << (8 * 2));
    GPIOF->OTYPER &= ~(1UL << 8);
    GPIOF->OSPEEDR |= (3UL << (8 * 2));

    // LCD D7 (PF9, A2) -> Output
    GPIOF->MODER  &= ~(3UL << (9 * 2));
    GPIOF->MODER  |=  (1UL << (9 * 2));
    GPIOF->OTYPER &= ~(1UL << 9);
    GPIOF->OSPEEDR |= (3UL << (9 * 2));

    // LCD RS (PA8, D10) -> Output
    GPIOA->MODER  &= ~(3UL << (8 * 2));
    GPIOA->MODER  |=  (1UL << (8 * 2));
    GPIOA->OTYPER &= ~(1UL << 8);

    // LCD E (PA15, D9) -> Output
    GPIOA->MODER  &= ~(3UL << (15 * 2));
    GPIOA->MODER  |=  (1UL << (15 * 2));
    GPIOA->OTYPER &= ~(1UL << 15);

    // Buzzer (PB4, D3) -> Alternate function 2 (TIM3_CH1)
    GPIOB->MODER  &= ~(3UL << (4 * 2));
    GPIOB->MODER  |=  (2UL << (4 * 2));   // 10 = alternate function
    GPIOB->OTYPER &= ~(1UL << 4);
    GPIOB->AFR[0] &= ~(0xFUL << (4 * 4));
    GPIOB->AFR[0] |=  (0x2UL << (4 * 4)); // AF2 = TIM3_CH1

    // ------------------------------------------------------------
    // TIMER 4 CONFIGURATION (free-running 1 ms ticker)
    // ------------------------------------------------------------
    // Timer 4 is 16-bit!!
    TIM4->PSC = 15999;        // Assumes 16MHz timer clock -> 1 tick per ms
    TIM4->ARR = 0xFFFF;       // Free-running, wraps every ~65 s
    TIM4->EGR = TIM_EGR_UG;   // Forces an update event to latch Prescaler value into hw registers
    TIM4->CR1 |= TIM_CR1_CEN; // Left running forever; TIM4_DelayMs only reads CNT

    // ------------------------------------------------------------
    // TIMER 3 CONFIGURATION (2 kHz PWM tone for the passive buzzer)
    // ------------------------------------------------------------
    TIM3->PSC  = 15;                  // 16 MHz / 16 = 1 MHz tick
    TIM3->ARR  = BUZZER_PERIOD - 1;   // 1 MHz / 500 = 2 kHz period
    TIM3->CCR1 = 0;                   // Start silent (0% duty)
    TIM3->CCMR1 &= ~(TIM_CCMR1_OC1M | TIM_CCMR1_CC1S); // CH1 as output, clear mode
    TIM3->CCMR1 |=  (6UL << 4);       // OC1M = 110 -> PWM mode 1
    TIM3->CCMR1 |=  (1UL << 3);       // OC1PE: CCR1 changes apply at the next period (no glitches)
    TIM3->CCER  |=  (1UL << 0);       // CC1E: connect CH1 to the pin
    TIM3->CR1   |=  (1UL << 7);       // ARPE: buffer ARR
    TIM3->EGR    =  TIM_EGR_UG;       // Latch PSC/ARR/CCR1
    TIM3->CR1   |=  TIM_CR1_CEN;      // Run forever; BUZZER_ON/OFF only change CCR1

    LCD_Initialize();
    LCD_DisplayString("Enter PIN:");
    LCD_Cmd(0xC0); // Move cursor to start of line 2 for the asterisks

    // Configure EXTI0
    SYSCFG->EXTICR[0] &= ~(0xFUL << (0 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (0 * 4));

    EXTI->IMR  |= (1UL << 0);  // Unmask line 0
    EXTI->FTSR |= (1UL << 0);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 0); // Disable rise register

    NVIC->ISER[0] |= (1UL << 6);         //Enable IRQ 6

    // Configure EXTI1
    SYSCFG->EXTICR[0] &= ~(0xFUL << (1 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (1 * 4));

    EXTI->IMR  |= (1UL << 1);  // Unmask line 1
    EXTI->FTSR |= (1UL << 1);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 1); // Disable rise register

    NVIC->ISER[0] |= (1UL << 7);         //Enable IRQ 7

    // Configure EXTI2
    SYSCFG->EXTICR[0] &= ~(0xFUL << (2 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (2 * 4));

    EXTI->IMR  |= (1UL << 2);  // Unmask line 2
    EXTI->FTSR |= (1UL << 2);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 2); // Disable rise register

    NVIC->ISER[0] |= (1UL << 8);         //Enable IRQ 8

    // Configure EXTI3
    SYSCFG->EXTICR[0] &= ~(0xFUL << (3 * 4));
    SYSCFG->EXTICR[0] |=  (0x8UL << (3 * 4));

    EXTI->IMR  |= (1UL << 3);  // Unmask line 3
    EXTI->FTSR |= (1UL << 3);  // Enable fall register
    EXTI->RTSR &= ~(1UL << 3); // Disable rise register

    NVIC->ISER[0] |= (1UL << 9);         //Enable IRQ 9

    while (1) {
        // ------------------------------------------------------------
        // MAIN LOOP STEP A: New keypress from the ISR
        // ------------------------------------------------------------
        if (key_ready) {
            key_ready = 0;

            Buzzer_Beep(BEEP_MS); // Start the beep first so it lines up with the press
            LCD_Data('*');        // Mask the key on line 2
        }

        // ------------------------------------------------------------
        // MAIN LOOP STEP B: Non-blocking buzzer timeout
        // ------------------------------------------------------------
        Buzzer_Update();
    }
}

void EXTI0_IRQHandler(void) {
    if (EXTI->PR & (1UL << 0)) {

		col_hits[0]++;

		char key = keypad_scan(3);   // PI0 = C4

		if (key) {
		    last_key = key;
		    key_ready = 1;
		}

		keypad_idle_state();

		EXTI->PR = 0xFUL; // Clear EXTI lines 0-3 (this key + any edges caused by the scan)
		NVIC->ICPR[0] = (1UL << 6);   // Clear NVIC Pending bit for IRQ6
    }
}

void EXTI1_IRQHandler(void) {
    if (EXTI->PR & (1UL << 1)) {

		col_hits[1]++;

		char key = keypad_scan(0);   // PI1 = C1

		if (key) {
		    last_key = key;
		    key_ready = 1;
		}

		keypad_idle_state();

		EXTI->PR = 0xFUL; // Clear EXTI lines 0-3 (this key + any edges caused by the scan)
		NVIC->ICPR[0] = (1UL << 7);   // Clear NVIC Pending bit for IRQ7
    }
}

void EXTI2_IRQHandler(void) {
    if (EXTI->PR & (1UL << 2)) {

		col_hits[2]++;

		char key = keypad_scan(1);   // PI2 = C2

		if (key) {
		    last_key = key;
		    key_ready = 1;
		}

		keypad_idle_state();

		EXTI->PR = 0xFUL; // Clear EXTI lines 0-3 (this key + any edges caused by the scan)
		NVIC->ICPR[0] = (1UL << 8);   // Clear NVIC Pending bit for IRQ8
    }
}

void EXTI3_IRQHandler(void) {
    if (EXTI->PR & (1UL << 3)) {

		col_hits[3]++;

		char key = keypad_scan(2);   // PI3 = C3

		if (key) {
		    last_key = key;
		    key_ready = 1;
		}

		keypad_idle_state();

		EXTI->PR = 0xFUL; // Clear EXTI lines 0-3 (this key + any edges caused by the scan)
		NVIC->ICPR[0] = (1UL << 9);   // Clear NVIC Pending bit for IRQ9
    }
}
